$events=$pdo->query('SELECT * FROM event ORDER BY tanggal ASC')->fetchAll();
?><!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Order Tiket</title><link rel='stylesheet' href='assets/style.css'></head><body class='batik'><div class='sky'></div><div class='cloud'></div><section class='section'><div class='container'><h1>Order Tiket Festival</h1><?php if(isset($_GET['ok']))echo "<div class='card' style='padding:12px'>Pesanan berhasil dikirim.</div>";?><div class='carousel card'><div class='slides'><img class='active' src='https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=1200&q=70'><img src='https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70'><img src='https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?auto=format&fit=crop&w=1200&q=70'></div><button class='car-btn car-prev' onclick='mv(-1)'>&lsaquo;</button><button class='car-btn car-next' onclick='mv(1)'>&rsaquo;</button></div><div class='grid g3' style='margin-top:14px'><?php foreach($events as $e):?><form class='card' method='post' style='padding:14px'><h3><?=$e['nama_event']?></h3><p><?=$e['lokasi']?> | <?=$e['tanggal']?></p><p>Harga: Rp<?=number_format($e['harga_tiket'])?> / tiket</p><input type='hidden' name='csrf' value='<?=$_SESSION['csrf']?>'><input type='hidden' name='event_id' value='<?=$e['id']?>'><input type='hidden' name='harga' value='<?=$e['harga_tiket']?>'><input name='nama' required placeholder='Nama Lengkap'><br><br><input name='email' required placeholder='Email Aktif'><br><br><input type='number' name='jumlah' min='1' value='1'><br><br><button class='btn btn-c'>Pesan Sekarang</button></form><?php endforeach;?></div><a class='btn' href='index.php'>← Kembali</a></div></section><script>let i=0;const imgs=[...document.querySelectorAll('.slides img')];function mv(d){imgs[i].classList.remove('active');i=(i+d+imgs.length)%imgs.length;imgs[i].classList.add('active');}</script></body></html>
